{"gameType":"stage-clear","input":"swipe-lanes","lang":"en","loop":"Guide your token through a small maze toward the glowing exit using swipes to move between lanes of the grid. Reaching the exit clears the maze and opens a new one; there is no way to fail, only to keep exploring.","slug":"tiny-maze","style":"chalkboard","title":"Tiny Maze"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Tiny Maze</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #2f3e3a;
11|     overflow: hidden;
12|     touch-action: none;
13|     font-family: 'Segoe UI', system-ui, sans-serif;
14|   }
15|   canvas {
16|     display: block;
17|     width: 100vw;
18|     height: 100dvh;
19|     background: #2f3e3a;
20|   }
21|   #hint {
22|     position: fixed;
23|     left: 0; right: 0; bottom: 10px;
24|     text-align: center;
25|     color: #eeeae0;
26|     opacity: 0.6;
27|     font-size: 13px;
28|     pointer-events: none;
29|     user-select: none;
30|   }
31| </style>
32| </head>
33| <body>
34| <canvas id="game"></canvas>
35| <div id="hint">Swipe left/right to change lanes &middot; swipe up/down or arrows to move forward/back</div>
36| <script>
37| // ---- Bridge helper (verbatim) ----
38| const CARTRIDGE = {
39|   send(type, payload = {}) {
40|     window.parent.postMessage(
41|       { source: "cartridge", v: 1, type, payload },
42|       "*",
43|     );
44|   },
45| };
46| 
47| window.addEventListener("message", (event) => {
48|   const data = event.data;
49|   if (!data || data.source !== "cartridge-host") return;
50|   if (data.type === "pause") paused = true;
51|   if (data.type === "resume") paused = false;
52|   if (data.type === "reset") backToTitle();
53| });
54| 
55| // ---- Canvas setup ----
56| const canvas = document.getElementById("game");
57| const ctx = canvas.getContext("2d");
58| let DPR = Math.max(1, window.devicePixelRatio || 1);
59| let W = 0, H = 0;
60| 
61| function resize() {
62|   W = window.innerWidth;
63|   H = window.innerHeight;
64|   DPR = Math.max(1, window.devicePixelRatio || 1);
65|   canvas.width = Math.floor(W * DPR);
66|   canvas.height = Math.floor(H * DPR);
67|   canvas.style.width = W + "px";
68|   canvas.style.height = H + "px";
69|   ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
70| }
71| window.addEventListener("resize", resize);
72| resize();
73| 
74| // ---- Palette ----
75| const COL = {
76|   slate: "#2f3e3a",
77|   chalk: "#eeeae0",
78|   accent: "#f2c14e",
79|   second: "#8fc1e3",
80| };
81| 
82| // ---- Chalk drawing helpers ----
83| function wobble(amount) {
84|   return (Math.random() - 0.5) * amount;
85| }
86| 
87| function chalkLine(x1, y1, x2, y2, color, width) {
88|   ctx.lineCap = "round";
89|   ctx.lineJoin = "round";
90|   for (let i = 0; i < 2; i++) {
91|     ctx.beginPath();
92|     const ox = wobble(1.4) + (i === 1 ? 1 : 0);
93|     const oy = wobble(1.4) + (i === 1 ? 1 : 0);
94|     const mx = (x1 + x2) / 2 + wobble(3);
95|     const my = (y1 + y2) / 2 + wobble(3);
96|     ctx.moveTo(x1 + ox, y1 + oy);
97|     ctx.quadraticCurveTo(mx + ox, my + oy, x2 + ox, y2 + oy);
98|     ctx.strokeStyle = color;
99|     ctx.globalAlpha = i === 0 ? 0.85 : 0.35;
100|     ctx.lineWidth = width;
101|     ctx.stroke();
102|   }
103|   ctx.globalAlpha = 1;
104| }
105| 
106| function chalkHatchRect(x, y, w, h, color, spacing) {
107|   spacing = spacing || 6;
108|   ctx.save();
109|   ctx.beginPath();
110|   ctx.rect(x, y, w, h);
111|   ctx.clip();
112|   for (let i = -h; i < w + h; i += spacing) {
113|     chalkLine(x + i, y, x + i - h, y + h, color, 2);
114|   }
115|   ctx.restore();
116| }
117| 
118| function chalkCircle(cx, cy, r, color, width) {
119|   const segs = 24;
120|   ctx.lineCap = "round";
121|   for (let pass = 0; pass < 2; pass++) {
122|     ctx.beginPath();
123|     for (let i = 0; i <= segs; i++) {
124|       const a = (i / segs) * Math.PI * 2;
125|       const rr = r + wobble(1.5);
126|       const x = cx + Math.cos(a) * rr + (pass === 1 ? 1 : 0);
127|       const y = cy + Math.sin(a) * rr + (pass === 1 ? 1 : 0);
128|       if (i === 0) ctx.moveTo(x, y);
129|       else ctx.lineTo(x, y);
130|     }
131|     ctx.strokeStyle = color;
132|     ctx.globalAlpha = pass === 0 ? 0.85 : 0.3;
133|     ctx.lineWidth = width;
134|     ctx.stroke();
135|   }
136|   ctx.globalAlpha = 1;
137| }
138| 
139| function drawSmudges() {
140|   const smudgeCount = 5;
141|   ctx.save();
142|   for (let i = 0; i < smudgeCount; i++) {
143|     const sx = smudgeSeeds[i].x * W;
144|     const sy = smudgeSeeds[i].y * H;
145|     const r = smudgeSeeds[i].r * Math.min(W, H);
146|     const grad = ctx.createRadialGradient(sx, sy, 0, sx, sy, r);
147|     grad.addColorStop(0, "rgba(238,234,224,0.05)");
148|     grad.addColorStop(1, "rgba(238,234,224,0)");
149|     ctx.fillStyle = grad;
150|     ctx.beginPath();
151|     ctx.ellipse(sx, sy, r, r * 0.6, smudgeSeeds[i].rot, 0, Math.PI * 2);
152|     ctx.fill();
153|   }
154|   ctx.restore();
155| }
156| 
157| const smudgeSeeds = [];
158| for (let i = 0; i < 6; i++) {
159|   smudgeSeeds.push({
160|     x: Math.random(),
161|     y: Math.random(),
162|     r: 0.15 + Math.random() * 0.2,
163|     rot: Math.random() * Math.PI,
164|   });
165| }
166| 
167| // ---- Maze / game state ----
168| const LANES = 4; // lane count across width
169| let laneCount = LANES;
170| let lane = 1; // current lane index (x)
171| let row = 0; // current row (progress toward exit, y)
172| let ROWS = 5; // rows per maze, grows a bit with stage
173| const TOTAL_STAGES = 8; // final stage triggers win
174| let stage = 0;
175| let score = 0;
176| let maze = []; // maze[row] = array of booleans: which lanes are open/walkable in that row
177| let exitRow = 0;
178| let started = false;
179| let paused = false;
180| let finished = false; // true once end has been sent, waiting for reset
181| let particles = [];
182| let messageTimer = 0;
183| let messageText = "";
184| let graceTimer = 0;
185| 
186| function backToTitle() {
187|   started = false;
188|   paused = false;
189|   finished = false;
190|   stage = 0;
191|   score = 0;
192|   row = 0;
193|   lane = Math.floor(LANES / 2);
194|   particles = [];
195| }
196| 
197| function randInt(n) {
198|   return Math.floor(Math.random() * n);
199| }
200| 
201| // Build a maze: each row has a random subset of walkable lanes (at least one),
202| // and consecutive rows always share at least one connected lane so it's always solvable.
203| function buildStage(s) {
204|   ROWS = 4 + Math.min(4, s); // grows slowly
205|   maze = [];
206|   // start row: all lanes open (safe start)
207|   let prevOpen = [true, true, true, true].slice(0, laneCount);
208|   maze.push(prevOpen.slice());
209|   for (let r = 1; r < ROWS; r++) {
210|     const openCount = 1 + randInt(laneCount - 1 >= 1 ? laneCount - 1 : 1);
211|     const lanes = [...Array(laneCount).keys()];
212|     // shuffle
213|     for (let i = lanes.length - 1; i > 0; i--) {
214|       const j = randInt(i + 1);
215|       [lanes[i], lanes[j]] = [lanes[j], lanes[i]];
216|     }
217|     let chosen = new Set(lanes.slice(0, Math.max(1, openCount)));
218|     // guarantee connectivity: ensure at least one lane open in prevOpen intersects with chosen
219|     const prevOpenLanes = [];
220|     for (let i = 0; i < laneCount; i++) if (prevOpen[i]) prevOpenLanes.push(i);
221|     const hasOverlap = prevOpenLanes.some((l) => chosen.has(l));
222|     if (!hasOverlap && prevOpenLanes.length > 0) {
223|       const forced = prevOpenLanes[randInt(prevOpenLanes.length)];
224|       chosen.add(forced);
225|     }
226|     const rowArr = [];
227|     for (let i = 0; i < laneCount; i++) rowArr.push(chosen.has(i));
228|     maze.push(rowArr);
229|     prevOpen = rowArr;
230|   }
231|   exitRow = ROWS - 1;
232|   // place player at a valid lane in row 0
233|   const startLanes = [];
234|   for (let i = 0; i < laneCount; i++) if (maze[0][i]) startLanes.push(i);
235|   lane = startLanes[randInt(startLanes.length)];
236|   row = 0;
237|   graceTimer = 2.5; // seconds of grace, though no threats exist
238|   messageText = "Reach the glowing exit \u2014 stage " + s + " / " + TOTAL_STAGES;
239|   messageTimer = 2.2;
240| }
241| 
242| function enterStage(next) {
243|   stage = next;
244|   buildStage(stage);
245|   CARTRIDGE.send("level", { index: stage });
246| }
247| 
248| function onGoalMet() {
249|   score += 10;
250|   CARTRIDGE.send("score", { value: score });
251|   particles = particles.concat(makeBurst());
252|   if (stage >= TOTAL_STAGES) {
253|     finished = true;
254|     messageText = "You escaped every maze!";
255|     messageTimer = 3;
256|     CARTRIDGE.send("end", { reason: "win", value: score });
257|   } else {
258|     enterStage(stage + 1);
259|   }
260| }
261| 
262| // try to move forward one row if current lane is open in next row
263| function tryAdvance(dir) {
264|   if (!started || paused || finished) return;
265|   const targetRow = row + dir;
266|   if (targetRow < 0) return;
267|   if (targetRow >= ROWS) return;
268|   if (maze[targetRow][lane]) {
269|     row = targetRow;
270|     if (row === exitRow) {
271|       onGoalMet();
272|     }
273|   } else {
274|     // bump feedback
275|     particles = particles.concat(makeBump());
276|   }
277| }
278| 
279| function tryLaneChange(dir) {
280|   if (!started || paused || finished) return;
281|   const newLane = Math.max(0, Math.min(laneCount - 1, lane + dir));
282|   if (newLane === lane) return;
283|   if (maze[row][newLane]) {
284|     lane = newLane;
285|   } else {
286|     particles = particles.concat(makeBump());
287|   }
288| }
289| 
290| function makeBurst() {
291|   const arr = [];
292|   for (let i = 0; i < 18; i++) {
293|     arr.push({
294|       x: 0, y: 0,
295|       vx: (Math.random() - 0.5) * 4,
296|       vy: (Math.random() - 0.5) * 4,
297|       life: 1,
298|       type: "burst",
299|       color: Math.random() < 0.5 ? COL.accent : COL.second,
300|     });
301|   }
302|   return arr;
303| }
304| 
305| function makeBump() {
306|   const arr = [];
307|   for (let i = 0; i < 6; i++) {
308|     arr.push({
309|       x: 0, y: 0,
310|       vx: (Math.random() - 0.5) * 2,
311|       vy: (Math.random() - 0.5) * 2,
312|       life: 0.5,
313|       type: "bump",
314|       color: COL.chalk,
315|     });
316|   }
317|   return arr;
318| }
319| 
320| // ---- Input: swipe lanes + forward/back ----
321| const SWIPE_FRACTION = 0.08;
322| let pressX = 0, pressY = 0;
323| canvas.addEventListener("pointerdown", (event) => {
324|   pressX = event.clientX;
325|   pressY = event.clientY;
326|   if (!started) {
327|     started = true;
328|     CARTRIDGE.send("start");
329|     enterStage(1);
330|     return;
331|   }
332|   if (finished) {
333|     backToTitle();
334|   }
335| });
336| canvas.addEventListener("pointerup", (event) => {
337|   const dx = event.clientX - pressX;
338|   const dy = event.clientY - pressY;
339|   const w = canvas.clientWidth;
340|   const h = canvas.clientHeight;
341|   if (Math.abs(dx) > Math.abs(dy)) {
342|     if (Math.abs(dx) < w * SWIPE_FRACTION) return;
343|     tryLaneChange(Math.sign(dx));
344|   } else {
345|     if (Math.abs(dy) < h * SWIPE_FRACTION) return;
346|     tryAdvance(dy < 0 ? 1 : -1);
347|   }
348| });
349| 
350| window.addEventListener("keydown", (e) => {
351|   if (!started) {
352|     if (e.key === "Enter" || e.key === " ") {
353|       started = true;
354|       CARTRIDGE.send("start");
355|       enterStage(1);
356|     }
357|     return;
358|   }
359|   if (finished) {
360|     if (e.key === "Enter" || e.key === " ") backToTitle();
361|     return;
362|   }
363|   if (e.key === "ArrowLeft") tryLaneChange(-1);
364|   if (e.key === "ArrowRight") tryLaneChange(1);
365|   if (e.key === "ArrowUp") tryAdvance(1);
366|   if (e.key === "ArrowDown") tryAdvance(-1);
367| });
368| 
369| // ---- Rendering ----
370| let lastTime = performance.now();
371| 
372| function drawTitleScreen() {
373|   ctx.clearRect(0, 0, W, H);
374|   drawSmudges();
375|   const cx = W / 2, cy = H / 2;
376|   ctx.font = "bold 34px system-ui, sans-serif";
377|   ctx.fillStyle = COL.chalk;
378|   ctx.textAlign = "center";
379|   ctx.globalAlpha = 0.9;
380|   ctx.fillText("Tiny Maze", cx, cy - 60);
381|   ctx.globalAlpha = 1;
382|   ctx.font = "16px system-ui, sans-serif";
383|   ctx.fillStyle = COL.second;
384|   ctx.fillText("Swipe or tap to begin", cx, cy - 20);
385| 
386|   chalkCircle(cx, cy + 40, 26, COL.accent, 4);
387|   ctx.font = "13px system-ui, sans-serif";
388|   ctx.fillStyle = COL.chalk;
389|   ctx.globalAlpha = 0.7;
390|   ctx.fillText("find the exit", cx, cy + 100);
391|   ctx.globalAlpha = 1;
392| }
393| 
394| function drawFinishScreen() {
395|   const cx = W / 2, cy = H / 2;
396|   ctx.font = "bold 30px system-ui, sans-serif";
397|   ctx.fillStyle = COL.accent;
398|   ctx.textAlign = "center";
399|   ctx.fillText("Maze Master!", cx, cy - 30);
400|   ctx.font = "18px system-ui, sans-serif";
401|   ctx.fillStyle = COL.chalk;
402|   ctx.fillText("Score " + score, cx, cy + 6);
403|   ctx.font = "14px system-ui, sans-serif";
404|   ctx.globalAlpha = 0.7;
405|   ctx.fillText("Tap to play again", cx, cy + 40);
406|   ctx.globalAlpha = 1;
407| }
408| 
409| function layoutMetrics() {
410|   const marginTop = 90;
411|   const marginBottom = 60;
412|   const fieldH = H - marginTop - marginBottom;
413|   const rowH = fieldH / ROWS;
414|   const fieldW = Math.min(W * 0.8, 420);
415|   const fieldX = (W - fieldW) / 2;
416|   const colW = fieldW / laneCount;
417|   return { marginTop, fieldH, rowH, fieldW, fieldX, colW };
418| }
419| 
420| function drawMaze() {
421|   const { marginTop, rowH, fieldW, fieldX, colW } = layoutMetrics();
422| 
423|   // draw rows from bottom (row 0) to top (exitRow), so exit appears at top
424|   for (let r = 0; r < ROWS; r++) {
425|     const y = marginTop + (ROWS - 1 - r) * rowH;
426|     for (let c = 0; c < laneCount; c++) {
427|       const x = fieldX + c * colW;
428|       const open = maze[r][c];
429|       if (open) {
430|         chalkHatchRect(x + 4, y + 4, colW - 8, rowH - 8, "rgba(143,193,227,0.25)", 8);
431|       } else {
432|         // wall X marks
433|         chalkLine(x + 6, y + 6, x + colW - 6, y + rowH - 6, "rgba(238,234,224,0.25)", 2);
434|         chalkLine(x + colW - 6, y + 6, x + 6, y + rowH - 6, "rgba(238,234,224,0.25)", 2);
435|       }
436|       // cell border
437|       chalkLine(x, y, x + colW, y, COL.chalk, 2);
438|       chalkLine(x, y, x, y + rowH, COL.chalk, 2);
439|     }
440|   }
441|   // outer border
442|   const totalH = rowH * ROWS;
443|   chalkLine(fieldX, marginTop, fieldX + fieldW, marginTop, COL.chalk, 3);
444|   chalkLine(fieldX, marginTop + totalH, fieldX + fieldW, marginTop + totalH, COL.chalk, 3);
445|   chalkLine(fieldX, marginTop, fieldX, marginTop + totalH, COL.chalk, 3);
446|   chalkLine(fieldX + fieldW, marginTop, fieldX + fieldW, marginTop + totalH, COL.chalk, 3);
447| 
448|   // exit glow
449|   const exitY = marginTop + (ROWS - 1 - exitRow) * rowH;
450|   for (let c = 0; c < laneCount; c++) {
451|     if (maze[exitRow][c]) {
452|       const x = fieldX + c * colW + colW / 2;
453|       const y = exitY + rowH / 2;
454|       const pulse = 0.5 + 0.5 * Math.sin(performance.now() / 300);
455|       chalkCircle(x, y, 14 + pulse * 4, COL.accent, 4);
456|     }
457|   }
458| 
459|   // player token
460|   const py = marginTop + (ROWS - 1 - row) * rowH + rowH / 2;
461|   const px = fieldX + lane * colW + colW / 2;
462|   chalkCircle(px, py, 12, COL.second, 4);
463|   chalkLine(px - 5, py, px + 5, py, COL.second, 2);
464|   chalkLine(px, py - 5, px, py + 5, COL.second, 2);
465| }
466| 
467| function drawHUD() {
468|   ctx.textAlign = "left";
469|   ctx.font = "16px system-ui, sans-serif";
470|   ctx.fillStyle = COL.chalk;
471|   ctx.globalAlpha = 0.85;
472|   ctx.fillText("Stage " + stage + " / " + TOTAL_STAGES, 16, 30);
473|   ctx.textAlign = "right";
474|   ctx.fillText("Score " + score, W - 16, 30);
475|   ctx.globalAlpha = 1;
476|   ctx.textAlign = "center";
477| 
478|   if (messageTimer > 0) {
479|     ctx.font = "18px system-ui, sans-serif";
480|     ctx.fillStyle = COL.accent;
481|     ctx.globalAlpha = Math.min(1, messageTimer);
482|     ctx.fillText(messageText, W / 2, 62);
483|     ctx.globalAlpha = 1;
484|   }
485| }
486| 
487| function updateParticles(dt) {
488|   const { fieldX, fieldW, marginTop, rowH } = layoutMetrics();
489|   const px = fieldX + lane * (fieldW / laneCount) + (fieldW / laneCount) / 2;
490|   const py = marginTop + (ROWS - 1 - row) * rowH + rowH / 2;
491|   for (const p of particles) {
492|     p.x += p.vx;
493|     p.y += p.vy;
494|     p.life -= dt * 1.2;
495|   }
496|   particles = particles.filter((p) => p.life > 0);
497|   ctx.save();
498|   for (const p of particles) {
499|     ctx.globalAlpha = Math.max(0, p.life);
500|     chalkCircle(px + p.x * 10, py + p.y * 10, 3, p.color, 2);
501|   }
502|   ctx.restore();
503|   ctx.globalAlpha = 1;
504| }
505| 
506| function frame(now) {
507|   const dt = Math.min(0.05, (now - lastTime) / 1000);
508|   lastTime = now;
509| 
510|   ctx.clearRect(0, 0, W, H);
511|   ctx.fillStyle = COL.slate;
512|   ctx.fillRect(0, 0, W, H);
513|   drawSmudges();
514| 
515|   if (!started) {
516|     drawTitleScreen();
517|   } else if (finished) {
518|     drawFinishScreen();
519|   } else {
520|     if (!paused) {
521|       if (messageTimer > 0) messageTimer -= dt;
522|       if (graceTimer > 0) graceTimer -= dt;
523|     }
524|     drawMaze();
525|     updateParticles(paused ? 0 : dt);
526|     drawHUD();
527|     if (paused) {
528|       ctx.font = "bold 28px system-ui, sans-serif";
529|       ctx.fillStyle = COL.chalk;
530|       ctx.textAlign = "center";
531|       ctx.fillText("Paused", W / 2, H / 2);
532|     }
533|   }
534| 
535|   requestAnimationFrame(frame);
536| }
537| 
538| // ---- Boot ----
539| function boot() {
540|   resize();
541|   ctx.fillStyle = COL.slate;
542|   ctx.fillRect(0, 0, W, H);
543|   requestAnimationFrame((t) => {
544|     lastTime = t;
545|     CARTRIDGE.send("boot", { title: "Tiny Maze", gameType: "stage-clear", lang: "en" });
546|     requestAnimationFrame(frame);
547|   });
548| }
549| boot();
550| </script>
551| </body>
552| </html>
553|

